"""Fixed-seed bounded property tests; generated bytes contain no user recordings."""

import json
import struct
import unittest

from hypothesis import example, given, seed, settings, strategies as st

from bridge import Bridge
from protocol import (
    EVENT,
    HEADER,
    MAX_PACKET,
    MIC,
    RENDER,
    SPEAKER,
    Packet,
    decode_event,
    decode_json_object,
    receive,
    validate_device_event,
)

FUZZ = settings(max_examples=150, deadline=500, database=None, print_blob=True)
SEED = 20261101


class Fragmented:
    def __init__(self, raw, chunk=7):
        self.raw = raw
        self.chunk = chunk
        self.read = 0

    def recv(self, count):
        count = min(count, self.chunk)
        result, self.raw = self.raw[:count], self.raw[count:]
        self.read += len(result)
        return result


class ProtocolFuzzTests(unittest.TestCase):
    @seed(SEED)
    @FUZZ
    @given(
        kind=st.sampled_from((MIC, RENDER, SPEAKER)),
        generation=st.integers(0, 2**32 - 1),
        sequence=st.integers(0, 2**64 - 1),
        frame=st.integers(0, 2**64 - 1),
        nanos=st.integers(0, 2**64 - 1),
        samples=st.binary(max_size=3200),
        chunk=st.integers(1, 100),
    )
    def test_pcm_roundtrip_survives_arbitrary_fragmentation(
        self, kind, generation, sequence, frame, nanos, samples, chunk
    ):
        packet = Packet(kind, generation, sequence, frame, nanos, samples + samples)
        stream = Fragmented(packet.encode(), chunk)
        self.assertEqual(receive(stream), packet)
        self.assertEqual(stream.raw, b'')

    @seed(SEED)
    @FUZZ
    @given(payload=st.binary(max_size=1024), chunk=st.integers(1, 128))
    @example(payload=b'x' * (MAX_PACKET - HEADER.size), chunk=128)
    def test_event_framing_roundtrip_is_independent_of_json_validation(self, payload, chunk):
        packet = Packet(EVENT, data=payload)
        self.assertEqual(receive(Fragmented(packet.encode(), chunk)), packet)

    @seed(SEED)
    @FUZZ
    @given(raw=st.binary(max_size=4096))
    def test_arbitrary_truncated_or_malformed_wire_never_reads_unbounded(self, raw):
        stream = Fragmented(raw)
        try:
            packet = receive(stream)
        except (EOFError, ValueError):
            pass
        else:
            self.assertLessEqual(len(packet.data), MAX_PACKET - HEADER.size)
            packet.encode()
        self.assertLessEqual(stream.read, MAX_PACKET + 4)

    @seed(SEED)
    @FUZZ
    @given(size=st.one_of(st.integers(0, HEADER.size - 1), st.integers(MAX_PACKET + 1, 2**32 - 1)))
    def test_invalid_size_fails_before_reading_body(self, size):
        stream = Fragmented(struct.pack('!I', size) + b'body')
        with self.assertRaises(ValueError):
            receive(stream)
        self.assertEqual(stream.read, 4)

    @seed(SEED)
    @FUZZ
    @given(samples=st.binary(max_size=2048), cut=st.integers(0, 65536))
    def test_truncation_at_every_frame_region_reports_eof(self, samples, cut):
        wire = Packet(MIC, data=samples + samples).encode()
        with self.assertRaises(EOFError):
            receive(Fragmented(wire[: cut % len(wire)]))

    @seed(SEED)
    @FUZZ
    @given(payload=st.binary(min_size=1, max_size=5000).filter(lambda data: len(data) % 2 == 1))
    def test_odd_pcm_is_rejected_in_both_directions(self, payload):
        with self.assertRaises(ValueError):
            Packet(MIC, data=payload).encode()
        raw = HEADER.pack(MIC, 0, 0, 0, 0) + payload
        with self.assertRaises(ValueError):
            receive(Fragmented(struct.pack('!I', len(raw)) + raw))

    def test_exact_pcm_size_type_and_integer_boundaries(self):
        Packet(MIC, data=b'\0' * 6400).encode()
        for packet in (
            Packet(MIC, data=b'\0' * 6402),
            Packet(EVENT, data=b'x' * (MAX_PACKET - HEADER.size + 1)),
            Packet(True),
            Packet(99),
            Packet(MIC, generation=True),
            Packet(MIC, generation=-1),
            Packet(MIC, generation=2**32),
            Packet(MIC, sequence=2**64),
            Packet(MIC, frame=-1),
            Packet(MIC, nanos=1.5),
            Packet(MIC, data='text'),
        ):
            with self.subTest(packet=packet):
                with self.assertRaises(ValueError):
                    packet.encode()


class JsonBoundaryTests(unittest.TestCase):
    @seed(SEED)
    @FUZZ
    @given(raw=st.binary(max_size=4096))
    @example(raw=b'{"event":"session_start","epoch":true}')
    @example(raw=b'{"event":"transport_auth","token":' + b'[' * 1100 + b']' * 1100 + b'}')
    def test_arbitrary_json_cannot_escape_as_parser_or_unicode_error(self, raw):
        try:
            value = decode_event(raw)
        except ValueError:
            pass
        else:
            self.assertIsInstance(value, dict)
            self.assertIsInstance(value['event'], str)

    def test_json_ambiguity_encoding_depth_and_node_budgets(self):
        invalid = (
            b'{"event":"x","event":"session_start","epoch":1}',
            b'{"event":"x","value":NaN}',
            b'{"event":"x","value":Infinity}',
            b'{"event":"x","value":1e999}',
            b'{"event":"x","value":"\\ud800"}',
            b'{"\\ud800":1}',
            '{"event":"x"}'.encode('utf-16'),
            b'{"event":"\xff"}',
            b'[]',
            b'null',
            b'1',
            b'{"event":"x","value":' + b'[' * 20 + b'0' + b']' * 20 + b'}',
            json.dumps({'event': 'x', 'value': [0] * 4096}).encode(),
            b'{"event":"x"',
        )
        for raw in invalid:
            with self.subTest(length=len(raw)):
                with self.assertRaises(ValueError):
                    decode_event(raw)
        with self.assertRaises(ValueError):
            decode_json_object(b'{"a":1}', max_bytes=4)

    @seed(SEED)
    @FUZZ
    @given(
        value=st.one_of(
            st.none(),
            st.booleans(),
            st.floats(),
            st.text(),
            st.lists(st.integers(), max_size=3),
            st.dictionaries(st.text(max_size=5), st.integers(), max_size=3),
        )
    )
    def test_invalid_epoch_never_starts_capture(self, value):
        bridge = Bridge(None, None)
        generation = bridge.generation
        with self.assertRaises(ValueError):
            bridge.on_event({'event': 'session_start', 'epoch': value})
        self.assertFalse(bridge.active)
        self.assertEqual(bridge.generation, generation)

    def test_missing_fields_and_truthy_strings_are_rejected_before_state_changes(self):
        for value in (
            {},
            {'event': []},
            {'event': 'session_start'},
            {'event': 'session_start', 'epoch': 1, 'capture_active': 'false'},
            {'event': 'settings', 'wake_mode': 1},
            {'event': 'play_done', 'generation': None},
            {'event': 'playback_paused', 'token': 1, 'generation': 2},
            {'event': 'screen_touch', 'extra': object()},
            {'event': 'screen_touch', 1: 'non-string key'},
        ):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    validate_device_event(value)


if __name__ == '__main__':
    unittest.main()
